31	 * 任务完成与目标事件遏制/当前事件解决按事务提交顺序形成合法结果、
32	 * 同 commandKey 并发单次生效及每事件 20 个任务上限的并发兜底。
33	 */
34	@SpringBootTest
35	class IncidentTaskConcurrencyTest {
36	
37	    @Autowired
38	    private IncidentService service;
39	
40	    @Autowired
41	    private JdbcTemplate jdbc;
42	
43	    @BeforeEach
44	    void clean() {
45	        jdbc.update("DELETE FROM command_keys");
46	        jdbc.update("DELETE FROM incident_status_history");
47	        jdbc.update("DELETE FROM incident_transfers");
48	        jdbc.update("DELETE FROM incident_actions");
49	        jdbc.update("DELETE FROM incident_task_blockers");
50	        jdbc.update("DELETE FROM incident_tasks");
51	        jdbc.update("DELETE FROM incidents");
52	    }
