                "SELECT COUNT(*) FROM incident_tasks WHERE incident_id = ?", Integer.class, incidentId);
        return count == null ? 0 : count;
    }

    /**
     * 将 OPEN 任务置为 DONE，记录完成人与 UTC 时刻。
     */
    public void markDone(long id, String actor, Instant at) {
