package com.example.starter.incident;

import java.time.Instant;

/**
 * 双人监护限时在场凭证实体，对应 task_presence_credentials 表。
 * 每人（taskId, role）代次从 1 开始，重新签到推进 +1 并使前代失效；
 * 有效期为 [issuedAt, expiresAt) 左闭右开，固定签发后 60 秒；
