        assertApiStatus(() -> service.revokePresence("INC-S7", "T-1", "alice",
                new PresenceRevokeRequest(key(), "op-exec", null)), HttpStatus.CONFLICT);
        assertApiStatus(() -> service.revokePresence("INC-S7", "T-1", "alice",
